#!/bin/zsh
set -euo pipefail
cd "${0:A:h}/.."
./Scripts/build.sh
version=$(/usr/libexec/PlistBuddy -c 'Print CFBundleShortVersionString' Packaging/Info.plist)
staging="$PWD/.build/package-root"
# This staging directory is generated by this script only.
if [[ -d "$staging" ]]; then /bin/rm -rf "$staging"; fi
mkdir -p "$staging/Applications"
ditto --norsrc dist/Pippy.app "$staging/Applications/Pippy.app"
pkgbuild --analyze --root "$staging" .build/components.plist
python3 - <<'PY'
import plistlib
from pathlib import Path
p = Path('.build/components.plist')
data = plistlib.loads(p.read_bytes())
for component in data:
    component['BundleIsRelocatable'] = False
    component['BundleOverwriteAction'] = 'upgrade'
p.write_bytes(plistlib.dumps(data))
PY
pkgbuild --root "$staging" --component-plist .build/components.plist --identifier com.heycling.pip.installer --version "$version" --install-location / "dist/Pippy-$version-arm64.pkg"
(cd dist && shasum -a 256 "Pippy-$version-arm64.pkg" > SHA256SUMS.txt)
print "Installer ready: dist/Pippy-$version-arm64.pkg"
